begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
create temporary table recovery_tap(line text);
grant all on recovery_tap to anon, authenticated, service_role;
set local role authenticated;
reset role;
set local role service_role;
reset role;

-- All network queue writes below are rolled back. pg_net starts requests only
-- after COMMIT; this suite must NEVER commit or make real provider requests.
delete from private.payment_recovery_dispatch;
delete from vault.secrets where name='suga_payment_worker_secret';
select vault.create_secret('short','suga_payment_worker_secret');
select vault.update_secret((select id from vault.secrets where name='suga_payment_worker_secret'),repeat('a',64)||E'\n');
select vault.update_secret((select id from vault.secrets where name='suga_payment_worker_secret'),repeat('a',513));
select vault.update_secret((select id from vault.secrets where name='suga_payment_worker_secret'),repeat('a',64));
create temporary table first_dispatch as select private.enqueue_payment_recovery() as request_id;
update private.payment_recovery_dispatch set dispatched_at = now()-interval '56 seconds';
select line from recovery_tap;
rollback;
