insert into recovery_tap select no_plan();
insert into recovery_tap select is((select count(*)::integer from cron.job where jobname='suga-payment-recovery'),1,'exactly one recovery job');
insert into recovery_tap select is((select schedule from cron.job where jobname='suga-payment-recovery'),'* * * * *','recovery scheduled every minute');
insert into recovery_tap select is((select command from cron.job where jobname='suga-payment-recovery'),'select private.enqueue_payment_recovery();','job command contains no credentials');
insert into recovery_tap select is((select username from cron.job where jobname='suga-payment-recovery'),'postgres','scheduler uses its intended database role');
insert into recovery_tap select ok(not (select prosecdef from pg_proc where oid='private.enqueue_payment_recovery()'::regprocedure),'dispatcher does not elevate caller privileges');
insert into recovery_tap select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='private.enqueue_payment_recovery()'::regprocedure),'dispatcher has empty search path');
insert into recovery_tap select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.payment_recovery_dispatch'::regclass),'private dispatch state has forced RLS');
insert into recovery_tap select ok(not has_function_privilege(r,'private.enqueue_payment_recovery()','execute'),r || ' cannot dispatch authenticated worker requests') from unnest(array['anon','authenticated','service_role']) r;
insert into recovery_tap select ok(not has_table_privilege(r,'private.payment_recovery_dispatch','select'),r || ' cannot read dispatch state') from unnest(array['anon','authenticated','service_role']) r;
insert into recovery_tap select ok(not has_table_privilege(r,'vault.decrypted_secrets','select'),r || ' cannot read the credential') from unnest(array['anon','authenticated']) r;
insert into recovery_tap select throws_ok('select private.enqueue_payment_recovery()','42501',null,'a signed-in customer/owner cannot dispatch');
insert into recovery_tap select throws_ok('select private.enqueue_payment_recovery()','42501',null,'application service role cannot invoke the database scheduler');
insert into recovery_tap select throws_ok('select private.enqueue_payment_recovery()','22023','payment_recovery_credential_not_configured','missing credential fails closed');
insert into recovery_tap select throws_ok('select private.enqueue_payment_recovery()','22023','payment_recovery_credential_not_configured','short credential fails closed');
insert into recovery_tap select throws_ok('select private.enqueue_payment_recovery()','22023','payment_recovery_credential_not_configured','header injection fails closed');
insert into recovery_tap select throws_ok('select private.enqueue_payment_recovery()','22023','payment_recovery_credential_not_configured','oversized credential fails closed');
insert into recovery_tap select ok((select request_id is not null from first_dispatch),'valid configuration enqueues one request');
insert into recovery_tap select ok(private.enqueue_payment_recovery() is null,'a repeated call cannot flood the endpoint');
insert into recovery_tap select is((select count(*)::integer from private.payment_recovery_dispatch),1,'bounded private dispatch state');
insert into recovery_tap select is((select q.url from net.http_request_queue q join first_dispatch d on d.request_id=q.id),'https://suga-spies-pastries.vercel.app/api/internal/payments/reconcile','only the approved HTTPS worker destination is used');
insert into recovery_tap select is((select q.method from net.http_request_queue q join first_dispatch d on d.request_id=q.id),'POST','worker is invoked with POST');
insert into recovery_tap select ok((select q.headers->>'Authorization' ~ '^Suga-Scheduler [1-9][0-9]{9,10}:[a-f0-9]{32}:[a-f0-9]{64}$' from net.http_request_queue q join first_dispatch d on d.request_id=q.id),'request uses a short-lived signature');
insert into recovery_tap select ok((select strpos(q.headers::text,repeat('a',64))=0 from net.http_request_queue q join first_dispatch d on d.request_id=q.id),'reusable credential is never queued');
insert into recovery_tap select ok((select split_part(q.headers->>'Authorization',':',3)=encode(extensions.hmac('suga-payment-recovery:v1:POST:/api/internal/payments/reconcile:'||split_part(substring(q.headers->>'Authorization' from 16),':',1)||':'||split_part(q.headers->>'Authorization',':',2),repeat('a',64),'sha256'),'hex') from net.http_request_queue q join first_dispatch d on d.request_id=q.id),'signature covers the method, action, timestamp and nonce');
insert into recovery_tap select is((select q.timeout_milliseconds from net.http_request_queue q join first_dispatch d on d.request_id=q.id),55000,'HTTP timeout stays below the worker budget');
insert into recovery_tap select ok(private.enqueue_payment_recovery() is not null,'a later scheduled attempt can proceed');
insert into recovery_tap select is((select count(*)::integer from private.payment_recovery_dispatch),1,'later dispatch replaces rather than grows the state');
insert into recovery_tap select * from finish();
